using System.Text.Json;
using DotReticulum.Applications.Rngit;
using DotReticulum.Core;
using DotReticulum.Tests.Interop;

namespace DotReticulum.Applications.Tests;

[Trait("Category", "Integration")]
public sealed class RngitPushTests
{
    // Generated by executing actual ReticulumGitNode handlers, not .NET output.
    // Hosted pin a29bfb51c468945c96a1ee22cae0114e993e2391; generator and source
    // SHA-256 provenance are recorded alongside Fixtures/rngit-push.json.
    [Fact]
    public void ReferenceStatuses_AgreeWithPushDecoder()
    {
        using var vectors = JsonDocument.Parse(File.ReadAllBytes(Path.Combine(AppContext.BaseDirectory, "Fixtures", "rngit-push.json")));
        Assert.Equal("a29bfb51c468945c96a1ee22cae0114e993e2391", vectors.RootElement.GetProperty("upstream").GetString());
        foreach (var vector in vectors.RootElement.GetProperty("cases").EnumerateArray())
        {
            var response = Convert.FromHexString(vector.GetProperty("response").GetString()!);
            var error = RngitSession.PushResponseError(response, null);
            Assert.Equal(vector.GetProperty("success").GetBoolean(), error is null);
            if (error is not null) Assert.Contains($"status {response[0]}", error);
        }
    }

    [Theory]
    [InlineData("")]
    [InlineData("04")]
    [InlineData("0061")]
    [InlineData("01ff")]
    public void InvalidStatus_IsNotSuccess(string hex)
    {
        var error = Record.Exception(() => RngitSession.PushResponseError(Convert.FromHexString(hex), null));
        Assert.True(error is ArgumentException or InvalidDataException);
    }

    [Fact]
    public void MetadataOnPushStatus_IsRejected() =>
        Assert.Throws<InvalidDataException>(() => RngitSession.PushResponseError([0], new Dictionary<object, object?>()));

    [Theory]
    [InlineData("refs/heads/main:refs/heads/main", "refs/heads/main", false)]
    [InlineData("+HEAD:refs/heads/main", "HEAD", true)]
    [InlineData(":refs/tags/old", "", false)]
    [InlineData("0123456789012345678901234567890123456789:refs/heads/new", "0123456789012345678901234567890123456789", false)]
    public void PushRefspec_ParsesSourcesAndForce(string text, string source, bool force)
    {
        var spec = RngitPushSpec.Parse(text);
        Assert.Equal(source, spec.Source);
        Assert.Equal(force, spec.Force);
    }

    [Theory]
    [InlineData("refs/heads/main")]
    [InlineData("HEAD:refs/heads/a..b")]
    [InlineData("HEAD:refs/heads/main:extra")]
    [InlineData("HEAD:refs/heads/injected\n")]
    [InlineData("HEAD :refs/heads/main")]
    [InlineData("+:refs/heads/main")]
    [InlineData("HEAD:HEAD")]
    public void PushRefspec_RejectsMalformedBeforeMutation(string text) =>
        Assert.Throws<InvalidDataException>(() => RngitPushSpec.Parse(text));

    [Fact]
    public void StatusQuoting_CannotInjectProtocolLines()
    {
        var quoted = RngitSession.QuoteStatus("bad \"ref\"\\\n\tcaf\u00e9");
        Assert.Equal("\"bad \\\"ref\\\"\\\\\\012\\011caf\\303\\251\"", quoted);
        Assert.DoesNotContain('\n', quoted);
        Assert.DoesNotContain('\r', quoted);
    }

    [Trait("Category", "Live")]
    [LiveFact]
    public async Task LivePush_ActualPinnedServer_BundlesOperationsForceDeleteAndFailureCleanup()
    {
        var root = Path.Combine(AppContext.BaseDirectory, "rngit-push-test-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(root);
        using var deadline = new CancellationTokenSource(TimeSpan.FromMinutes(2));
        var stop = deadline.Token;
        var local = Directory.CreateDirectory(Path.Combine(root, "local.git")).FullName;
        var repositories = Directory.CreateDirectory(Path.Combine(root, "repositories")).FullName;
        var remote = Path.Combine(repositories, "sample.git");
        Task<string> Git(string directory, params string[] args) => RngitClient.GitAsync(directory, args, stop);
        async Task<string> Commit(string text, string? parent = null)
        {
            var blob = (await RngitClient.GitAsync(local, ["hash-object", "-w", "--stdin"], stop, text)).Trim();
            var tree = (await RngitClient.GitAsync(local, ["mktree"], stop, $"100644 blob {blob}\tfile.txt\n")).Trim();
            return (await Git(local, ["-c", "user.name=Disposable fixture", "-c", "user.email=fixture@example.invalid",
                "commit-tree", tree, "-m", text, .. (parent is null ? Array.Empty<string>() : new[] { "-p", parent })])).Trim();
        }
        try
        {
            await Git(local, "init", "--bare", "--initial-branch=main", ".");
            var first = await Commit("first\n");
            await Git(local, "update-ref", "refs/heads/main", first);
            await Git(local, "-c", "protocol.file.allow=always", "clone", "--bare", local, remote);
            var second = await Commit("second\n", first);
            await Git(local, "update-ref", "refs/heads/main", second);
            await Git(local, "-c", "user.name=Disposable fixture", "-c", "user.email=fixture@example.invalid",
                "tag", "-a", "new-tag", "-m", "new annotation", second);
            var snapshot = await Git(local, "show-ref");

            using var identity = Identity.Generate();
            var port = ReticulumNodeTests.FreePort();
            await using var python = await PyLinkNode.StartAsync("push", tcpServerPort: port, harness: "live_rngit_node.py",
                extraArguments: ["--repositories", repositories, "--writer", Convert.ToHexStringLower(identity.Hash)]);
            var config = Directory.CreateDirectory(Path.Combine(root, "client")).FullName;
            await File.WriteAllTextAsync(Path.Combine(config, "config"), $"""
                [reticulum]
                  share_instance = no
                  enable_transport = no
                [interfaces]
                  [[Python]]
                    type = TCPClientInterface
                    enabled = yes
                    target_host = 127.0.0.1
                    target_port = {port}
                """, stop);
            await using var node = ReticulumNode.Open(config);
            await node.StartAsync(stop);
            var client = new RngitClient(node, identity);
            using var session = await client.OpenSessionAsync($"rns://{python.HashHex}/fixtures/sample.git",
                TimeSpan.FromSeconds(45), 16 * 1024 * 1024, stop, forPush: true);
            async Task<RngitPushResult> Push(string refspec) => await session.PushAsync(local, RngitPushSpec.Parse(refspec), stop);
            var result = await Push("refs/heads/main:refs/heads/main");
            Assert.Null(result.Error);
            Assert.True(result.BundleBytes > 0);
            Assert.Equal(second, (await Git(remote, "rev-parse", "refs/heads/main")).Trim());
            result = await Push(second + ":refs/heads/existing");
            Assert.Null(result.Error);
            Assert.Equal(0, result.BundleBytes);
            result = await Push(second + ":refs/heads/existing");
            Assert.Null(result.Error);
            Assert.Equal(0, result.BundleBytes);
            result = await Push("refs/tags/new-tag:refs/tags/new-tag");
            Assert.Null(result.Error);
            Assert.True(result.BundleBytes > 0);
            Assert.Equal((await Git(local, "rev-parse", "refs/tags/new-tag")).Trim(),
                (await Git(remote, "rev-parse", "refs/tags/new-tag")).Trim());

            result = await Push(first + ":refs/heads/main");
            Assert.Contains("force required", result.Error);
            Assert.Equal(second, (await Git(remote, "rev-parse", "refs/heads/main")).Trim());
            Assert.Null((await Push("+" + first + ":refs/heads/main")).Error);
            result = await Push(second + ":refs/heads/main");
            Assert.Contains("force required", result.Error);
            Assert.Equal(0, result.BundleBytes);
            Assert.Null((await Push("+" + second + ":refs/heads/main")).Error);

            var divergent = await Commit("divergent\n", first);
            result = await Push(divergent + ":refs/heads/main");
            Assert.Contains("status 255", result.Error);
            Assert.Equal(second, (await Git(remote, "rev-parse", "refs/heads/main")).Trim());
            Assert.Null((await Push("+" + divergent + ":refs/heads/main")).Error);
            Assert.Null((await Push(":refs/heads/existing")).Error);
            Assert.Null((await Push(":refs/heads/existing")).Error);
            Assert.Null((await Push(":refs/tags/new-tag")).Error);
            Assert.Equal("refs/heads/main", (await Git(remote, "symbolic-ref", "HEAD")).Trim());

            using var readOnly = await client.OpenSessionAsync($"rns://{python.HashHex}/readonly/sample.git",
                TimeSpan.FromSeconds(30), 16 * 1024 * 1024, stop);
            result = await readOnly.PushAsync(local, RngitPushSpec.Parse(first + ":refs/heads/denied"), stop);
            Assert.Contains("status 1", result.Error);
            result = await readOnly.PushAsync(local, RngitPushSpec.Parse(":refs/heads/main"), stop);
            Assert.Contains("status 1", result.Error);
            using var stranger = Identity.Generate();
            using var unauthorized = await new RngitClient(node, stranger).OpenSessionAsync($"rns://{python.HashHex}/fixtures/sample.git",
                TimeSpan.FromSeconds(30), 16 * 1024 * 1024, stop);
            result = await unauthorized.PushAsync(local, RngitPushSpec.Parse(first + ":refs/heads/denied"), stop);
            Assert.Contains("status 1", result.Error);

            var oversized = await Commit("never sent\n", divergent);
            await Assert.ThrowsAsync<InvalidDataException>(() =>
                session.PushAsync(local, RngitPushSpec.Parse(oversized + ":refs/heads/oversized"), stop, maxBundleBytes: 1));
            await Assert.ThrowsAsync<IOException>(() => Git(remote, "rev-parse", "--verify", "refs/heads/oversized"));
            using var cancelled = new CancellationTokenSource();
            cancelled.Cancel();
            await Assert.ThrowsAnyAsync<OperationCanceledException>(() =>
                session.PushAsync(local, RngitPushSpec.Parse(":refs/heads/main"), cancelled.Token));
            Assert.Equal(divergent, (await Git(remote, "rev-parse", "refs/heads/main")).Trim());
            Assert.Empty(Directory.GetDirectories(local, "rngit-push-*"));
            Assert.Equal(snapshot, await Git(local, "show-ref"));
            await Git(remote, "fsck", "--full", "--strict");
        }
        finally
        {
            foreach (var file in Directory.EnumerateFiles(root, "*", SearchOption.AllDirectories))
                File.SetAttributes(file, File.GetAttributes(file) & ~FileAttributes.ReadOnly);
            TestDirectory.DeleteWithRetry(root);
        }
    }
}
